mapper.select:
SELECT 
FROM share_link
WHERE owner_id = #{ownerId}
  AND root_entry_id = #{rootEntryId}
LIMIT 1

mapper.update:
UPDATE share_link
SET revoked_at = CURRENT_TIMESTAMP(6)
WHERE owner_id = #{ownerId} AND id = #{id}

mapper.insert:
INSERT INTO share_access_log (
    share_id, viewer_user_id, access_action, succeeded
) VALUES (
    #{shareId}, #{viewerUserId}, #{action}, #{succeeded}
)

mapper.select:
SELECT COUNT(*)
FROM share_access_log
WHERE share_id = #{shareId}
  AND access_action = #{action}

  AND succeeded = 1
